mapper.select:
SELECT , LEAST(1.0, CASE WHEN POSITION(#{query} IN LOWER(c.file_path))>0 THEN .75 ELSE 0 END +CASE WHEN POSITION(#{query} IN LOWER(COALESCE(c.symbol_name,'')))>0 THEN .95 ELSE 0 END +CASE WHEN POSITION(#{query} IN LOWER(c.content))>0 THEN .65 ELSE 0 END +(
CASE WHEN LOWER(COALESCE(c.symbol_name,''))=#{term} THEN .85 WHEN POSITION(#{term} IN LOWER(COALESCE(c.symbol_name,'')))>0 THEN .65 WHEN POSITION(#{term} IN LOWER(c.file_path))>0 THEN .5 WHEN POSITION(#{term} IN LOWER(c.content))>0 THEN .3 ELSE 0 END
) / #{termCount} ) lexical_score,0.0 semantic_score FROM code_chunks c WHERE c.repo_id=#{repositoryId} AND( POSITION(#{query} IN LOWER(c.file_path))>0 OR POSITION(#{query} IN LOWER(COALESCE(c.symbol_name,'')))>0 OR POSITION(#{query} IN LOWER(c.content))>0
OR POSITION(#{term} IN LOWER(c.file_path))>0 OR POSITION(#{term} IN LOWER(COALESCE(c.symbol_name,'')))>0 OR POSITION(#{term} IN LOWER(c.content))>0
) ORDER BY lexical_score DESC,c.file_path,c.start_line NULLS FIRST LIMIT #{limit}

SELECT , LEAST(1.0, CASE WHEN POSITION(#{query} IN LOWER(c.title))>0 THEN .95 ELSE 0 END +CASE WHEN POSITION(#{query} IN LOWER(c.content))>0 THEN .65 ELSE 0 END +CASE WHEN POSITION(#{query} IN LOWER(ARRAY_TO_STRING(c.tags,' ')))>0 THEN .8 ELSE 0 END +(
CASE WHEN POSITION(#{term} IN LOWER(c.title))>0 THEN .7 WHEN POSITION(#{term} IN LOWER(ARRAY_TO_STRING(c.tags,' ')))>0 THEN .6 WHEN POSITION(#{term} IN LOWER(c.content))>0 THEN .35 ELSE 0 END
) / #{termCount} ) lexical_score,0.0 semantic_score FROM knowledge_cards c WHERE AND( POSITION(#{query} IN LOWER(c.title))>0 OR POSITION(#{query} IN LOWER(c.content))>0 OR POSITION(#{query} IN LOWER(ARRAY_TO_STRING(c.tags,' ')))>0
OR POSITION(#{term} IN LOWER(c.title))>0 OR POSITION(#{term} IN LOWER(c.content))>0 OR POSITION(#{term} IN LOWER(ARRAY_TO_STRING(c.tags,' ')))>0
) ORDER BY lexical_score DESC,c.updated_at DESC LIMIT #{limit}

SELECT c.id,c.repo_id,c.title,c.question,c.provider,c.evidence_status,c.fallback_reason,
c.created_at,c.updated_at,COUNT(q.id) citation_count
FROM qa_conversations c LEFT JOIN qa_citations q ON q.conversation_id=c.id
WHERE c.repo_id=#{repositoryId} AND c.account_id=#{accountId}
GROUP BY c.id ORDER BY c.created_at DESC,c.id DESC LIMIT #{limit} OFFSET #{offset}
